const body = $input.first().json;
const record = body.record ?? body;
const emails = record.emails ?? {};
const name = record.name ?? {};
const email =
  emails.primaryEmail ??
  record.email ??
  (Array.isArray(emails) ? emails[0] : '') ??
  '';
const firstName = name.firstName ?? record.firstName ?? '';
const lastName = name.lastName ?? record.lastName ?? '';

if (!email) {
  throw new Error('Twenty person payload has no primaryEmail');
}

const listIdRaw = $env.BREVO_CRM_LIST_ID;
const listIds = listIdRaw ? [Number(listIdRaw)] : [];

return [
  {
    json: {
      email,
      firstName,
      lastName,
      companyId: record.companyId ?? null,
      personId: record.id ?? null,
      brevoBody: {
        email,
        attributes: {
          FIRSTNAME: firstName,
          LASTNAME: lastName,
        },
        listIds,
        updateEnabled: true,
      },
    },
  },
];
